/**
 * Legacy mind maps for TinyMCE
 *
 * Released under the MIT license.
 * Original plugin: Ignacio Gros (http://gros.es/) for http://exelearning.net/
 *
 * eXeLearning used to create mind maps with mindmaps (https://www.mindmaps.app/) through this
 * plugin. That editor is no longer included: new diagrams are Mermaid diagrams (exemermaid).
 *
 * A legacy map (<div class="exe-mind-map">: a PNG plus the mindmaps JSON in
 * <p class="exe-mindmap-code">) is kept unchanged. When the author selects one, a contextual
 * button offers to convert it to a Mermaid mindmap, which exemermaid then edits as any other
 * diagram. The conversion keeps the figure caption and moves the original JSON, unchanged,
 * next to the diagram as archived data; nothing reads it afterwards.
 */
tinymce.PluginManager.add('exemindmap', function (editor, url) {

    function getLegacyMap(node) {
        var map = node ? editor.dom.getParent(node, '.exe-mind-map') : null;
        if (!map || !map.querySelector('img') || !map.querySelector('.exe-mindmap-code')) return null;
        return map;
    }

    function encode(text) {
        return tinymce.DOM.encode(text);
    }

    // Resolves with the SVG preview, or with '' when Pele is not available here
    function renderPreview(source) {
        if (typeof $exe === 'undefined' || !$exe.mermaid) return Promise.resolve('');
        return $exe.mermaid.load().then(
            function (pele) {
                return pele.render(source, { fontFamily: $exe.mermaid.fontFamily }).svg;
            },
            function () {
                return '';
            }
        );
    }

    // Replaces the legacy map, in one undo step, with:
    // <div class="exe-mindmap-converted"><figure>(<pre class="mermaid"> + caption)</figure><p class="exe-mindmap-code"></div>
    function replaceMap(map, source) {
        var dom = editor.dom;
        editor.undoManager.transact(function () {
            var img = map.querySelector('img');
            var code = map.querySelector('.exe-mindmap-code');
            var figure = map.querySelector('figure');
            var pre = dom.create('pre', { 'class': 'mermaid' });
            pre.textContent = source;
            var wrapper = dom.create('div', { 'class': 'exe-mindmap-converted' });
            if (figure && figure.contains(img)) {
                var link = dom.getParent(img, 'a', figure);
                var media = link || img;
                media.parentNode.replaceChild(pre, media);
                // The width and the image class were the PNG's
                dom.setStyle(figure, 'width', null);
                dom.removeClass(figure, 'exe-image');
                if (!figure.querySelector('figcaption') && img.getAttribute('alt')) {
                    dom.setAttrib(figure, 'aria-label', img.getAttribute('alt'));
                }
                wrapper.appendChild(figure);
            } else {
                wrapper.appendChild(pre);
            }
            wrapper.appendChild(code);
            dom.replace(wrapper, map);
            editor.selection.select(pre);
        });
        editor.nodeChanged();
    }

    function openDialog(map, converted, svg) {
        var preview = svg
            ? '<div role="group" aria-label="' + encode(_('Preview of the Mermaid diagram')) + '" style="max-height:45vh;overflow:auto;border:1px solid #ccc;padding:.5em;background:#fff">' + svg + '</div>'
            : '<p>' + encode(_('The preview is not available, but the diagram will be shown once the iDevice is saved.')) + '</p>';
        editor.windowManager.open({
            title: _('Convert to Mermaid'),
            size: 'large',
            body: {
                type: 'panel',
                items: [
                    {
                        type: 'htmlpanel',
                        html:
                            '<p>' + encode(_('This mind map was made with the previous mind map editor, which is no longer included in eXeLearning. You can keep it as it is, as an image, or convert it to a Mermaid diagram that you can edit as text.')) + '</p>' +
                            '<p><strong>' + encode(_('The conversion keeps the text of every node (%s) and how they are organised, but not the colours, fonts, styles, positions of the branches or the layout. Folded branches are shown unfolded. The image is replaced by the diagram, and the original map data is kept in the page.').replace('%s', converted.nodes)) + '</strong></p>' +
                            preview
                    }
                ]
            },
            buttons: [
                { type: 'cancel', name: 'cancel', text: _('Cancel') },
                { type: 'submit', name: 'convert', text: _('Convert to Mermaid'), primary: true }
            ],
            onSubmit: function (api) {
                api.close();
                replaceMap(map, converted.source);
            }
        });
    }

    function showConversionError() {
        editor.windowManager.alert(_('This mind map cannot be converted to Mermaid because its data is damaged or too large. The map has not been changed.'));
    }

    function convertSelectedMap() {
        var map = getLegacyMap(editor.selection.getNode());
        if (!map) return;
        var converted;
        try {
            converted = window.SharedImporters.legacyMindmap.convertLegacyMindmapCode(
                map.querySelector('.exe-mindmap-code').innerHTML
            );
        } catch (error) {
            console.warn('[exemindmap]', error);
            showConversionError();
            return;
        }
        renderPreview(converted.source).then(
            function (svg) {
                openDialog(map, converted, svg);
            },
            function (error) {
                // Pele loaded but could not draw the diagram: do not replace the map with it
                console.warn('[exemindmap]', error);
                showConversionError();
            }
        );
    }

    editor.ui.registry.addButton('exemindmapconvert', {
        text: _('Convert to Mermaid'),
        tooltip: _('Convert this mind map to a Mermaid diagram'),
        onAction: convertSelectedMap
    });

    editor.ui.registry.addContextToolbar('exemindmap', {
        predicate: function (node) {
            return getLegacyMap(node) !== null;
        },
        items: 'exemindmapconvert',
        position: 'node',
        scope: 'node'
    });

    editor.on('init', function () {
        editor.dom.loadCSS(url + '/css/content.css');
        // Says what the map is; generated content, so it is never saved
        editor.dom.addStyle('.exe-mind-map::before{content:' + JSON.stringify(_('Mind map from the previous editor. Select it to convert it to Mermaid.')) + '}');
    });

});
